@dataclass
class PhysicalConnection:
    device1: str = ""
    port1: str = ""
    place1: str = ""
    type: str = ""
    device2: str = ""
    port2: str = ""
    place2: str = ""
    cable: str = ""


class InventoryServices(CMaintenance):
    """
        Class with definition of private methods related to
        Inventory handling.

        Services:
        get_device_information
        get_devices_in_folder
        update_device_by_csv
        get_all_device_ports
        device_physical_connections
        devices_physical_connections_from_list
        device_physical_connections_csv
        write_physical_connections_to_csv
        check_permission_to_edit_resource
        move_physical_connections
        copy_ports_from_template_to_device
    """
    logger = Log.get_logger("velocityclient")

    def get_device_information(self, device_name, get_properties=True):
        device = self.get_devices(filter=f'name::{device_name}')
        if not device["devices"]:
            raise RestQueryException(f"Device {device_name} not found.")
        if get_properties:
            return self.get_device(device["devices"][0]["id"])
        return device["devices"][0]

    def get_devices_in_folder(self, folder_name="", folder_id="", searchString=""):
        if folder_name != "":
            folder = self._get_folder_info(folder_name)
            folder_id = folder["id"]
        limit = 200
        offset = limit
        devices_in_folder = []
        print("GETTING DEVICES IN FOLDER")
        devices = self.get_devices(filter=f'folderId::{folder_id}', limit=limit, searchString=searchString)
        devices_in_folder.extend(devices["devices"])
        total_all = devices["total"]
        if total_all > limit:
            while offset < total_all:
                devices = self.get_devices(filter=f'folderId::{folder_id}', limit=limit, offset=offset, searchString=searchString)
                devices_in_folder.extend(devices["devices"])
                offset += limit
        if len(devices_in_folder) != total_all:
            raise RestQueryException(f"Error in getting devices in folder {folder_name}.")
        print(f"Devices from folder {folder_name}: {len(devices_in_folder)}")
        return devices_in_folder

    def update_device_by_csv(self, csv_keys, csv_values, type="device"):
        """
        Update device properties by CSV file.
        type: "device" or "connections"

        "device" type is used to update device properties like name, serial number, etc.
        "connections" type is used to update physical connections between devices.
        """
        output = io.StringIO()
        writer = csv.writer(
                        output,
                        quotechar='"',
                        delimiter=',',
                        quoting=csv.QUOTE_MINIMAL,
                        skipinitialspace=True)

        # Write the header
        writer.writerow(csv_keys)

        # Write the rows
        if type == "device":
            writer.writerow(csv_values)
        elif type == "connections":
            writer.writerows(csv_values)
        else:
            raise ValueError("Invalid type specified. Use 'device' or 'connections'.")

        # Get the CSV string
        csv_string = output.getvalue()
        output.close()
        if type == "device":
            import_result = self.import_inventory_csv(body=csv_string)
        elif type == "connections":
            import_result = self.import_physical_connections_csv(body=csv_string)
        else:
            raise ValueError("Invalid type specified. Use 'device' or 'connections'.")
        # import_result = self.import_inventory_csv(body=csv_string)
        started_waiting = time.time()
        import_status = ""
        while time.time() < started_waiting + 200:
            time.sleep(2)
            import_job = self.get_job(import_result["jobId"])
            import_status = import_job["status"]
            if import_status != "SCHEDULED":
                print("Property update: ", import_status)
                errors = [item["message"] for item in import_job['result']['details']
                          if item['status'] in ['FAILED']]
                if errors:
                    raise Exception('Import failed! Details: ' + '. '.join(errors))
                return import_status
        raise Exception(f'Import failed! Status: {import_status} Job: {import_result["jobId"]}')

    def get_all_device_ports(self, device_id, properties=False, filter="", connected=False):
        """
        Get all ports of a device by its id.
        :param device_id: Id of the device
        :param properties: Include properties in the response
        :param filter: Filter string for ports
        :param connected: If True, only return connected ports
        :return: List of ports
        """
        ports = []
        limit = 200
        
        # Build kwargs conditionally
        kwargs = {
            'device_id': device_id,
            'limit': limit,
            'includeProperties': properties
        }
        
        # Only add filter if it's not empty
        if filter and filter.strip():
            kwargs['filter'] = filter
        
        device_ports = self.get_device_ports(**kwargs)
        ports.extend(device_ports['ports'])
        total_all = device_ports["total"]
        offset = limit
        
        if total_all > limit:
            while offset < total_all:
                kwargs['offset'] = offset
                device_ports = self.get_device_ports(**kwargs)
                ports.extend(device_ports["ports"])
                offset += limit
        
        msg = f"Total of ports {total_all} for {device_id}."
        self.logger.info(msg)
        if connected is True:
            connected_ports = []
            for port in ports:
                if port["connectedPortId"] is not None or port["backConnectedPortId"] is not None:
                    connected_ports.append(port)
            return connected_ports
        return ports

    def device_physical_connections(self, device_name):
        """
        Return device physical connections in a list of dataclass objects.
        Added checks that device1 is always the device that was queried and
        device2 the other end of the connection.
        Parameters returned in list object
            device1: str
            port1: str
            place1: str
            type: str
            device2: str
            port2: str
            place2: str
            cable: str
        """
        connection_list = []
        connections = self._get_physical_connections_list_by_name(device_name)
        for connection in connections:
            main_device, target_device = "1", "2"
            if connection["device1"]["name"] != device_name:
                main_device, target_device = "2", "1"
            if connection[f"device{main_device}"]["name"] != device_name:
                continue
            data_obj = PhysicalConnection()
            data_obj.device1 = connection[f"device{main_device}"]["name"]
            data_obj.port1 = connection[f"port{main_device}"]["name"]
            data_obj.place1 = connection[f"place{main_device}"]
            data_obj.device2 = connection[f"device{target_device}"]["name"]
            data_obj.port2 = connection[f"port{target_device}"]["name"]
            data_obj.place2 = connection[f"place{target_device}"]
            data_obj.type = connection["type"]
            if connection["cable"] is not None:
                data_obj.cable = connection["cable"]["name"]
            connection_list.append(data_obj)
        return connection_list

    def devices_physical_connections_from_list(self, device_list):
        """
        Return physical connections for all devices on a list.
        Check for duplicate entries so that only unique connections are returned.

        Physical connection object format:
            device1: str,
            port1: str,
            place1: str,
            type: str,
            device2: str,
            port2: str,
            place2: str,
            cable: str


        :param device_list: List of device names

        :return: List of physical connection objects from the devices in device_list.
                 If none found in any of the devices, returns an empty list.

        """
        def get_connections(device_name):
            try:
                return self.device_physical_connections(device_name)
            except Exception:
                return []

        _futures = list()
        all_connections = []

        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            # Submit all jobs first
            for device in device_list:
                _futures.append(executor.submit(get_connections, device))
            # Collect all results after all jobs are submitted
            for future in concurrent.futures.as_completed(_futures):
                try:
                    result = future.result()
                    if result is not None:
                        all_connections.extend(result)
                except Exception as e:
                    self.logger.error(f"Error in thread: {e}")

        parsed_connections = self._parse_and_remove_duplicate_connections(all_connections, device_list)

        return parsed_connections

    def device_physical_connections_csv(self, devices, location=""):
        """
        If devices is a list, all physical connections are gathered and written to a csv file.
        If devices is a single device, only that device's physical connections are gathered
        and written to a csv file.
        """
        if type(devices) is list:
            connections = self.devices_physical_connections_from_list(devices)
            devices = devices[0]
        else:
            connections = self.device_physical_connections(devices)

        self.write_physical_connections_to_csv(connections, location)
        return 0

    def write_physical_connections_to_csv(self, connections, location=""):
        if location == "":
            name = 'physical_connections'
            location = r'C:\tmp\\' + name + '.csv'
        os.makedirs(os.path.dirname(location), exist_ok=True)
        with open(location, 'w', newline='') as file:
            csv_rowlist = []
            writer = csv.writer(file)
            field = ["device1",
                     "port1",
                     "place1",
                     "type",
                     "device2",
                     "port2",
                     "place2",
                     "cable"]
            csv_rowlist.append(field)
            for con in connections:
                if con.cable == "":
                    row = [con.device1,
                           con.port1,
                           con.place1,
                           con.type,
                           con.device2,
                           con.port2,
                           con.place2,
                           ""]
                else:
                    row = [con.device1,
                           con.port1,
                           con.place1,
                           con.type,
                           con.device2,
                           con.port2,
                           con.place2,
                           con.cable]
                csv_rowlist.append(row)
            writer.writerows(csv_rowlist)
            file.close()

    def check_permission_to_edit_resource(self, device, user_permissions=None):
        """
        Check if user has rights to edit the device.
        :param device: Device information dictionary
        :type device: dict
        """
        group_permissions = []
        resource_groups_list = device["deviceGroups"]
        for group_id in resource_groups_list:
            permissions = self.get_device_group_user_group_permissions(group_id=group_id)
            for permission_id, permission_value in permissions["permissions"].items():
                if 'RESOURCE_GROUP_ADMIN' in permission_value:
                    group_permissions.append(permission_id)
        if user_permissions is None:
            user_permissions = self.get_current_user()
        user_groups = user_permissions["groups"]
        user_group_ids = [g["id"] for g in user_groups]
        if not any(group in user_group_ids for group in group_permissions) and \
           user_permissions["role"] != "ADMIN":
            raise Exception("User does not have admin or group admin permissions to perform this operation!")

    def move_physical_connections(self,
                                  source,
                                  destination,
                                  connected_check=True,
                                  template_check=True,
                                  location=""):
        """
        Move physical connections from source to destination device.
        Checks if the user has permission to edit both devices.
        If the source device has connected devices, it checks if the user
        has permission also to edit those devices, unless connected_check is set to False.
        Destination device must not have any physical connections before moving connections.
        Check if destination device has the same ports as source device connected.

        :param source: Name of the source device
        :param destination: Name of the destination device
        :param connected_check: If True, permission check for connected devices.
        :param template_check: If True, checks if both devices are using the same template.
        :param location: Location to save the CSV file with physical connections. e.g. "C:\\tmp\\connections.csv"
        :return: SUCCESS
        """
        # Get device information
        user_permissions = self.get_current_user()
        source_device = self.get_device_information(source)
        destination_device = self.get_device_information(destination)
        if template_check is True and source_device["templateId"] != destination_device["templateId"]:
            raise Exception("Source and destination devices are not using the same template. "
                            "Please use devices with the same template to move physical connections.")
        self.check_permission_to_edit_resource(source_device, user_permissions)
        self.check_permission_to_edit_resource(destination_device, user_permissions)

        source_ports = self.get_all_device_ports(source_device["id"])
        destination_ports = self.get_all_device_ports(destination_device["id"])

        device_ids = []
        connected_ports = [port["name"] for port in source_ports
                           if port["connectedPortId"] or port["backConnectedPortId"]]
        print(f"Connected ports in source device: {connected_ports}")

        for port in source_ports:
            if port["connectedPortParentId"] is not None \
               and port["connectedPortParentId"] not in device_ids:
                device_ids.append(port["connectedPortParentId"])
            if port["backConnectedPortParentId"] is not None \
               and port["backConnectedPortParentId"] not in device_ids:
                device_ids.append(port["backConnectedPortParentId"])

        if connected_check:
            if device_ids:
                no_permission_devices = []

                def check_permission(dev):
                    dev_info = self.get_device(dev)
                    try:
                        self.check_permission_to_edit_resource(dev_info, user_permissions)
                        return None
                    except Exception:
                        return dev_info["name"]

                with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
                    results = list(executor.map(check_permission, device_ids))

                # Filter out None values (devices with permission)
                no_permission_devices = [name for name in results if name is not None]
                if no_permission_devices != []:
                    raise Exception("User does not have permission to edit the following devices: " +
                                    f"{', '.join(no_permission_devices)}")

        d_port_list = [port["name"] for port in destination_ports]
        missing_ports = [port for port in connected_ports if port not in d_port_list]
        print("Destination ports: ", d_port_list)
        if missing_ports:
            raise Exception(
                "Source and destination devices do not have the same ports to connect. "
                f"Missing in destination: {', '.join(missing_ports)}")

        source_connections = self.devices_physical_connections_from_list([source_device["name"]])
        destination_connections = self.devices_physical_connections_from_list([destination_device["name"]])

        source_connections_list = [
                con for con in source_connections
                if con.device1 == source_device["name"]]
        destination_connections_list = [
                con for con in destination_connections
                if con.device1 == destination_device["name"]]

        if source_connections_list == []:
            raise Exception("Source device does not have any physical connections to move.")

        if destination_connections_list != []:
            raise Exception("Destination device already has physical connections. "
                            "Please remove them before moving connections from source device.")

        if location == "":
            location = r'C:\tmp\\' + source + '-physical_connections.csv'
        self.write_physical_connections_to_csv(connections=source_connections_list,
                                               location=location)
        for con in source_connections_list:
            new_con = PhysicalConnection(
                device1=destination_device["name"],
                port1=con.port1,
                place1=con.place1,
                type=con.type,
                device2=con.device2,
                port2=con.port2,
                place2=con.place2,
                cable=con.cable
            )
            destination_connections_list.append(new_con)

        cvs_body = self._connections_to_csv_body(destination_connections_list)
        result = self.update_device_by_csv(csv_keys=cvs_body["header"],
                                           csv_values=cvs_body["rows"],
                                           type="connections")
        return result

    def copy_ports_from_template_to_device(self, template_name, device_name):
        """
        Copy ports from a template to a device.

        Delete port groups and all ports of device defined.
        Copy port groups and ports from defined template
        and create them to device.

        :param template_name: Name of the template from which to copy ports
        :param device_name: Name of the device to which ports will be copied
        """
        # Gathering information
        template = self._get_template_info(template_name)
        template_ports = self._get_template_ports(template["id"])
        port_body_list = self._generate_device_ports_body(template_ports)
        template_info = self.get_template(template["id"])
        template_groups = template_info["portGroups"]
        device_info = self.get_device_information(device_name)

        # Delete groups and ports from device
        for group in device_info["portGroups"]:
            if group["id"] is None or group["parentId"] is not None:
                continue
            try:
                self.delete_device_port_group(device_info["id"], group["id"])
            except Exception as e:
                raise Exception(
                    f'Error deleting port group {group["name"]} '
                    f'from device {device_name}. Error: {e}'
                )

        device_ports = self.get_all_device_ports(device_info["id"])
        for port in device_ports:
            try:
                self.delete_device_port(device_info["id"], port["id"])
            except Exception as e:
                raise Exception(
                    f'Error deleting port {port["name"]} '
                    f'from device {device_name}. Error: {e}'
                )

        # Create port groups in device based on template groups
        old_new_group_ids = {}
        top_level_groups = [g for g in template_groups if not g.get("parentId")]
        for top_group in top_level_groups:
            if top_group["id"] is None:
                continue
            try:
                new_g = self.create_device_port_group(
                    device_info["id"],
                    {"name": top_group["name"]}
                )
            except Exception as e:
                raise Exception(
                    f'Error creating port group {top_group["name"]} '
                    f'in device {device_name}. Error: {e}'
                )
            old_new_group_ids[top_group["id"]] = new_g["id"]
        sub_groups = [g for g in template_groups if g.get("parentId")]
        for sub_g in sub_groups:
            parentId = old_new_group_ids.get(sub_g["parentId"], None)
            if parentId is None:
                raise Exception(
                    f'Parent group id {sub_g["parentId"]} '
                    f'not found in old_new_group_ids.'
                )
            body = {"name": sub_g["name"], "parentId": parentId}
            try:
                new_g = self.create_device_port_group(device_info["id"], body)
            except Exception as e:
                raise Exception(
                    f'Error creating port group {sub_g["name"]} '
                    f'in device {device_name}. Error: {e}'
                )
            old_new_group_ids[sub_g["id"]] = new_g["id"]

        # Create the ports
        for port_info in port_body_list:
            port_info["groupId"] = old_new_group_ids.get(port_info["groupId"], "")

        body = {"ports": port_body_list}
        self.logger.debug("Ports creation body: ", body)
        try:
            self.create_device_ports(device_info["id"], body)
        except Exception as e:
            raise Exception(
                f'Error creating ports in device {device_name}. Error: {e}'
            )

        return {"status": "success", "message": "Ports copied successfully."}

    def delete_resources_from_folder(self, folder_id):
        """
        Delete all resources in a folder by its id.
        :param folder_id: Id of the folder
        """
        permission = self.get_current_user()
        devices = self.get_devices_in_folder(folder_id=folder_id)
        failed_to_delete = []
        def delete_single_device(device):
            """Helper function to delete a single device"""
            try:
                self.check_permission_to_edit_resource(device, permission)
            except Exception as e:
                print(f"No permission to {device['name']}: {e}")
                return device["id"]
            
            try:
                result = self.delete_device(device["id"])
                return result
            except Exception as e:
                print(f"Failed to delete {device['name']}: {e}")
                return device["id"]

        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
            future_to_device = {executor.submit(delete_single_device, device): device
                            for device in devices}

            for future in concurrent.futures.as_completed(future_to_device):
                try:
                    result = future.result()
                    if result is not None:  # Device delestion failed
                        failed_to_delete.append(result)
                except Exception as e:
                    device = future_to_device[future]
                    print(f"Thread error for device {device['name']}: {e}")
                    failed_to_delete.append(device["id"])
        print(f"Total devices in folder: {len(devices)}")
        print(f"Failed to delete total: {len(failed_to_delete)}")
        print(f"Failed to delete id's: {failed_to_delete}")
        return {"status": "completed",
                "total_devices": len(devices),
                "failed_to_delete": failed_to_delete}

    def delete_all_device_ports(self, device_id, port_filter="", connected=False):
        device_ports =  self.get_all_device_ports(device_id, filter=port_filter, connected=connected)
        failed_to_delete = []
        delete_counter = 0
        print("Total ports to delete: ", len(device_ports))

        def delete_single_port(port):
            """Helper function to delete a single port"""
            try:
                self.delete_device_port(device_id, port["id"])
                return None  # Success
            except Exception as e:
                self.logger.error(f"Failed to delete port {port['name']} from device {device_id}: {e}")
                return port["name"]  # Return failed port name

        # Use ThreadPoolExecutor with 10 workers
        with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
            # Submit all deletion jobs
            future_to_port = {executor.submit(delete_single_port, port): port 
                            for port in device_ports}
            
            # Collect results as they complete
            for future in concurrent.futures.as_completed(future_to_port):
                try:
                    result = future.result()
                    if result is None:  # Port deletion succeeded
                        delete_counter += 1
                    else:  # Port deletion failed
                        failed_to_delete.append(result)
                except Exception as e:
                    port = future_to_port[future]
                    self.logger.error(f"Thread error for port {port['name']}: {e}")
                    failed_to_delete.append(port["name"])

        print(f"Total ports deleted: {delete_counter}")
        print(f"Failed to delete ports: {len(failed_to_delete)}")
        return {"status": "completed",
                "total_ports": len(device_ports),
                "ports_deleted": delete_counter,
                "failed_to_delete": failed_to_delete}

    def advanced_search(self, limit=10, searchString: str = '', offset=0, collect_all=True):
        """ searchString can be as used in advanced search """
        search = urllib.parse.quote(str(searchString))
        
        # Get initial response
        response = self.get_device_search(searchString=search, limit=limit, offset=offset)
        all_devices = response.get('devices', [])
        total_all = response.get('total', 0)
        
        # If there are more results than the limit, collect them all
        if collect_all and total_all > limit:
            current_offset = limit + offset
            
            while current_offset < total_all:
                additional_response = self.get_device_search(
                    searchString=search, 
                    limit=limit, 
                    offset=current_offset
                )
                all_devices.extend(additional_response.get('devices', []))
                current_offset += limit
        
        # Update response with all collected devices
        response['devices'] = all_devices
        response['count'] = len(all_devices)
        
        return response

    def remove_connected_physical_connections(self, device_ids_list):
        for device_id in device_ids_list:
            device_ports = self.get_all_device_ports(device_id=device_id)
            print(device_ports)
            print(f"Removing connections from device {device_id}, total ports: {len(device_ports)}")
            if not device_ports:
                continue
            body = []
            for port in device_ports:
                body.append({
                    "port1Id": port["id"],
                    "port2Id": None,
                    "type": None
                })
            self.update_physical_connections(body=body)

    def get_connected_ports_id_list(self, device_name):
        port_id_list = []
        connections = self._get_physical_connections_list_by_name(device_name)
        for connection in connections:
            main_device, target_device = "1", "2"
            if connection["device1"]["name"] != device_name:
                main_device, target_device = "2", "1"
            if connection[f"device{main_device}"]["name"] != device_name:
                continue
            port_id_list.append(connection[f"port{main_device}"]["id"])
        return port_id_list
